package com.geutilities;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptID;
import net.runelite.api.KeyCode;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(name = "GE Utilities")
public class GEUtilitiesPlugin extends Plugin
{
	private static final int GE_GROUP_ID = 465;

	// Minimap parent widgets per layout mode. Hiding these removes the minimap area.
	// Resizable and pre-eoc: fully hidden. Fixed classic: freezes the image (engine limitation).
	private static final int[] MINIMAP_WIDGETS = {
		InterfaceID.ToplevelOsrsStretch.MAP_MINIMAP,  // resizable (stretch)
		InterfaceID.ToplevelPreEoc.MAP_MINIMAP,        // pre-eoc resizable
		InterfaceID.Toplevel.MAPCONTAINER,              // fixed classic (child 9)
	};

	// Orb containers (HP, prayer, run, spec) per layout mode
	private static final int[] ORB_WIDGETS = {
		InterfaceID.ToplevelOsrsStretch.ORBS,
		InterfaceID.ToplevelPreEoc.ORBS,
		InterfaceID.Toplevel.ORBS,
	};

	@Inject
	private Client client;

	@Inject
	private GEUtilitiesConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GEBlackoutOverlay blackoutOverlay;

	private boolean geOpen;

	@Provides
	GEUtilitiesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GEUtilitiesConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(blackoutOverlay);
		clientThread.invokeLater(() ->
		{
			Widget geWidget = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
			geOpen = geWidget != null && !geWidget.isHidden();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(blackoutOverlay);
		clientThread.invokeLater(() -> setMinimapHidden(false));
		geOpen = false;
	}

	boolean isGeOpen()
	{
		return geOpen;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!geOpen || !config.blockWalking())
		{
			return;
		}

		if (event.getMenuAction() == MenuAction.WALK)
		{
			event.consume();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == GE_GROUP_ID)
		{
			geOpen = true;
			if (config.disableMinimap())
			{
				setMinimapHidden(true);
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == GE_GROUP_ID)
		{
			geOpen = false;
			setMinimapHidden(false);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (geOpen)
		{
			setMinimapHidden(config.disableMinimap());
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.TOPLEVEL_REDRAW
			|| event.getScriptId() == ScriptID.TOPLEVEL_RESIZE_CUSTOMISE)
		{
			if (geOpen)
			{
				setMinimapHidden(config.disableMinimap());
			}
		}
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (client.isMenuOpen())
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();

		if (config.shiftClickAbort() && client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			swapAbortOffer(menu, entries);
		}
		else if (config.swapGEModify())
		{
			swapModifyOffer(menu, entries);
		}
	}

	private void setMinimapHidden(boolean hide)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// Respect the vanilla minimap toggle so we don't accidentally unhide
		// a minimap the player has hidden through game settings
		boolean vanillaHide = client.getVarbitValue(VarbitID.MINIMAP_TOGGLE) == 1;

		for (int packedId : MINIMAP_WIDGETS)
		{
			setWidgetTreeHidden(packedId, hide || vanillaHide);
		}

		for (int packedId : ORB_WIDGETS)
		{
			setWidgetTreeHidden(packedId, hide);
		}
	}

	private void setWidgetTreeHidden(int packedId, boolean hide)
	{
		Widget w = client.getWidget(packedId);
		if (w == null)
		{
			return;
		}

		w.setHidden(hide);
		Widget[] children = w.getChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child != null)
				{
					child.setHidden(hide);
				}
			}
		}
	}

	private void swapAbortOffer(Menu menu, MenuEntry[] entries)
	{
		int topIdx = entries.length - 1;
		int abortIdx = -1;

		for (int i = 0; i < entries.length; i++)
		{
			String option = Text.removeTags(entries[i].getOption()).toLowerCase();
			if (option.equals("abort offer"))
			{
				abortIdx = i;
				break;
			}
		}

		if (abortIdx >= 0 && abortIdx != topIdx)
		{
			MenuEntry temp = entries[topIdx];
			entries[topIdx] = entries[abortIdx];
			entries[abortIdx] = temp;

			if (entries[topIdx].getType() == MenuAction.CC_OP_LOW_PRIORITY)
			{
				entries[topIdx].setType(MenuAction.CC_OP);
			}

			menu.setMenuEntries(entries);
		}
	}

	private void swapModifyOffer(Menu menu, MenuEntry[] entries)
	{
		int topIdx = entries.length - 1;
		int modifyIdx = -1;
		int viewIdx = -1;

		for (int i = 0; i < entries.length; i++)
		{
			String option = Text.removeTags(entries[i].getOption()).toLowerCase();
			if (option.equals("modify offer"))
			{
				modifyIdx = i;
			}
			else if (option.equals("view offer"))
			{
				viewIdx = i;
			}
		}

		if (modifyIdx < 0)
		{
			return;
		}

		int swapTarget = config.supersedeSwaps() ? topIdx : viewIdx;

		if (swapTarget >= 0 && modifyIdx != swapTarget)
		{
			MenuEntry temp = entries[swapTarget];
			entries[swapTarget] = entries[modifyIdx];
			entries[modifyIdx] = temp;

			if (entries[swapTarget].getType() == MenuAction.CC_OP_LOW_PRIORITY)
			{
				entries[swapTarget].setType(MenuAction.CC_OP);
			}

			menu.setMenuEntries(entries);
		}
	}
}

package com.geutilities;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class GEBlackoutOverlay extends Overlay
{
	private static final Color BLACK = new Color(0, 0, 0, 255);

	private final Client client;
	private final GEUtilitiesPlugin plugin;
	private final GEUtilitiesConfig config;

	@Inject
	GEBlackoutOverlay(Client client, GEUtilitiesPlugin plugin, GEUtilitiesConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isGeOpen() || !config.blackoutViewport())
		{
			return null;
		}

		graphics.setColor(BLACK);
		graphics.fillRect(
			client.getViewportXOffset(),
			client.getViewportYOffset(),
			client.getViewportWidth(),
			client.getViewportHeight()
		);

		return null;
	}
}

package com.geutilities;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("geutilities")
public interface GEUtilitiesConfig extends Config
{
	@ConfigItem(
		keyName = "swapGEModify",
		name = "Offer left-click Modify",
		description = "Swap left-click from View offer to Modify offer on Grand Exchange slots.",
		position = 1
	)
	default boolean swapGEModify()
	{
		return false;
	}

	@ConfigItem(
		keyName = "shiftClickAbort",
		name = "Offer shift-click Abort",
		description = "Swap left-click to Abort offer when holding Shift on Grand Exchange slots.",
		position = 2
	)
	default boolean shiftClickAbort()
	{
		return false;
	}

	@ConfigItem(
		keyName = "supersedeSwaps",
		name = "Override other plugin swaps",
		description = "Place swapped options at the top of the menu instead of their original position, ensuring this plugin's swaps take effect even when other plugins' swaps reorder the menu.",
		position = 3
	)
	default boolean supersedeSwaps()
	{
		return false;
	}

	@ConfigItem(
		keyName = "disableMinimap",
		name = "Hide minimap in GE",
		description = "Hide the minimap and orbs while the Grand Exchange is open. In fixed classic mode the minimap is frozen instead of hidden.",
		position = 4
	)
	default boolean disableMinimap()
	{
		return false;
	}

	@ConfigItem(
		keyName = "blockWalking",
		name = "Block walking in GE",
		description = "Prevent walk clicks while the Grand Exchange is open.",
		position = 5
	)
	default boolean blockWalking()
	{
		return false;
	}

	@ConfigItem(
		keyName = "blackoutViewport",
		name = "Blackout viewport in GE",
		description = "Cover the game world with a black overlay while the Grand Exchange is open.",
		position = 6
	)
	default boolean blackoutViewport()
	{
		return false;
	}
}
